    helpSubtitle: 'FAQ, support and Bloomly contacts',
    helpTabFaq: 'FAQ',
    helpTabReport: 'Report a problem',
    helpTabTickets: 'My tickets',
    helpTabContacts: 'Contacts',
    helpFaqQ1: 'How do I change my profile picture or banner?',
    helpFaqA1: 'Go to "Settings → Profile" and click your avatar or banner to upload a new image. You can crop the avatar right in the editor before saving.',
    helpFaqQ2: 'What is verification and how do I get it?',
    helpFaqA2: 'Verification confirms that an account belongs to a real person and fits one of the categories: artist, master, fursuiter, writer, organizer, etc. Requests are submitted from "Settings → Verification" and reviewed manually by moderators — there is no automatic approval. Your profile must be at least 80% complete (avatar, fursona, email).',
    helpFaqQ3: 'How do I create a group and who can manage it?',
    helpFaqA3: 'Click "Create" in the "Groups" section. The creator automatically becomes the owner and can transfer ownership to another member using a one-time confirmation code in the group settings.',
    helpFaqQ4: "What is Dealers' Den?",
    helpFaqA4: "Dealers' Den is a marketplace for artists and crafters: seller storefronts, listings, bids, fairs, and a reputation system (Trust Score). Open your own storefront from the Dealers' Den section in the sidebar.",
    helpFaqQ5: 'How do stickers and the shop work?',
    helpFaqA5: 'The "Shop" lets you buy sticker packs with in-app currency or real money. Purchased packs appear in your collection and are available when sending messages and comments.',
    helpFaqQ6: 'What does the "Automation" section do?',
    helpFaqA6: 'Automation helps you set up recurring actions and reminders related to activities and tasks within the platform.',
    helpFaqQ7: 'My account is frozen or banned — what do I do?',
    helpFaqA7: 'For a frozen account, the login screen will offer to confirm your identity with a one-time email code and unfreeze it yourself. For a ban, contact support via "Report a problem" below or at support@bloomly.fun, mentioning your username and the issue.',
    helpFaqQ8: 'How do I configure profile privacy?',
    helpFaqA8: 'In "Settings → Privacy" you can separately restrict who sees your friends list, online status, or can message you or comment on your posts: "everyone", "friends only", or "only me".',
    helpFaqQ9: 'How do I report a post, comment or user?',
    helpFaqA9: 'Most posts, comments and profiles have a flag-icon button — it sends a report straight to moderators without needing to contact support.',
    helpFaqQ10: 'Can I delete or export my data?',
    helpFaqA10: 'Yes. Data export and account deletion are available in "Settings → Profile", at the very bottom of the page. Data handling details are described in the Privacy Policy.',
    helpReportIntro: 'Describe a bug, an idea, or a question — moderators will see it and reply right here, in the "My tickets" tab.',
