    helpFaqQ1: 'プロフィール写真やバナーはどうやって変更しますか?',
    helpFaqA1: '「設定→プロフィール」に移動し、アバターまたはバナーをクリックして新しい画像をアップロードしてください。保存前にエディター内でアバターをトリミングできます。',
    helpFaqQ2: '認証とは何ですか?どうすれば取得できますか?',
    helpFaqA2: '認証は、アカウントが実在の人物のものであり、アーティスト、職人、着ぐるみ愛好家、作家、主催者などのカテゴリーのいずれかに該当することを確認するものです。申請は「設定→認証」から行い、モデレーターが手動で審査します(自動承認はありません)。プロフィールは80%以上完成している必要があります(アバター、フルソナ、メール)。',
