    helpFaqQ4: "Dealers' Denとは何ですか?",
    helpFaqA4: "Dealers' Denはアーティストや職人向けのマーケットプレイスです:出品者の店舗、出品、入札、フェア、評判システム(Trust Score)があります。サイドバーのDealers' Denセクションから自分の店舗を開くことができます。",
    helpFaqQ5: 'ステッカーとショップの仕組みを教えてください。',
    helpFaqA5: '「ショップ」ではアプリ内通貨または実際のお金でステッカーパックを購入できます。購入したパックはコレクションに表示され、メッセージやコメント送信時に使用できます。',
    helpFaqQ6: '「自動化」セクションは何をしますか?',
    helpFaqA6: '自動化機能は、プラットフォーム内のアクティビティやタスクに関連する繰り返しの操作やリマインダーを設定するのに役立ちます。',
    helpFaqQ7: 'アカウントが凍結またはBANされました。どうすればいいですか?',
    helpFaqA7: 'アカウントが凍結されている場合、ログイン画面でメールのワンタイムコードによる本人確認と、ご自身での凍結解除が案内されます。BANされた場合は、以下の「問題を報告」またはsupport@bloomly.funまで、ユーザー名と内容を添えてご連絡ください。',
    helpFaqQ8: 'プロフィールのプライバシー設定はどうすればいいですか?',
