    helpTabTickets: '我的工单',
    helpTabContacts: '联系方式',
    helpFaqQ1: '如何更改头像或横幅?',
    helpFaqA1: '前往"设置→个人资料",点击头像或横幅即可上传新图片。保存前可以在编辑器中直接裁剪头像。',
    helpFaqQ2: '什么是认证?如何获得认证?',
    helpFaqA2: '认证用于确认账号属于真实用户,并归属于以下类别之一:画师、匠人、兽装爱好者、作家、组织者等。申请需在"设置→认证"中提交,由管理员人工审核 — 没有自动通过。个人资料完整度须达到80%以上(头像、兽形设定、邮箱)。',
    helpFaqQ3: '如何创建群组?谁可以管理群组?',
    helpFaqA3: '在"群组"页面点击"创建"。创建者会自动成为群主,并可通过群组设置中的一次性验证码将权限转让给其他成员。',
    helpFaqQ4: "什么是 Dealers' Den?",
    helpFaqA4: "Dealers' Den 是面向画师和手工艺人的交易平台:含卖家店铺、商品、竞价、集市以及信誉体系(Trust Score)。可从侧边栏的 Dealers' Den 板块开设自己的店铺。",
    helpFaqQ5: '贴纸和商店是如何运作的?',
    helpFaqA5: '在"商店"中可以使用平台内货币或真实货币购买贴纸包。购买的贴纸包会出现在你的收藏中,并可在发送消息和评论时使用。',
    helpFaqQ6: '"自动化"板块有什么作用?',
    helpFaqA6: '自动化功能可帮助你设置与平台内活动和任务相关的重复操作与提醒。',
    helpFaqQ7: '我的账号被冻结或封禁了,该怎么办?',
    helpFaqA7: '若账号被冻结,登录页会提示通过邮箱一次性验证码确认身份并自行解冻。若账号被封禁,请通过下方"反馈问题"或发送邮件至 support@bloomly.fun 联系我们,并注明你的用户名和具体情况。',
    helpFaqQ8: '如何设置个人资料隐私?',
    helpFaqA8: '在"设置→隐私"中,可分别限制谁能查看你的好友列表、在线状态,以及谁可以给你发消息或评论你的帖子:"所有人"、"仅好友"或"仅自己"。',
    helpFaqQ9: '如何举报帖子、评论或用户?',
    helpFaqA9: '大多数帖子、评论和个人资料都有一个旗帜图标按钮 — 它会直接向管理员发送举报,无需联系支持团队。',
    helpFaqQ10: '我可以删除或导出自己的数据吗?',
    helpFaqA10: '可以。数据导出和账号删除功能位于"设置→个人资料"页面的最底部。数据处理的详细说明请参阅隐私政策。',
