    help: 'Hilfe',
    helpSubtitle: 'FAQ, Support und Kontakte von Bloomly',
    helpTabFaq: 'Häufige Fragen',
    helpTabReport: 'Problem melden',
    helpTabTickets: 'Meine Anfragen',
    helpTabContacts: 'Kontakte',
    helpFaqQ1: 'Wie ändere ich mein Profilbild oder Banner?',
    helpFaqA1: 'Gehe zu "Einstellungen → Profil" und klicke auf dein Avatar oder Banner, um ein neues Bild hochzuladen. Der Avatar kann direkt im Editor zugeschnitten werden, bevor du speicherst.',
    helpFaqQ2: 'Was ist die Verifizierung und wie erhalte ich sie?',
    helpFaqA2: 'Die Verifizierung bestätigt, dass ein Konto einer echten Person gehört und zu einer der Kategorien gehört: Künstler, Handwerker, Fursuiter, Autor, Organisator usw. Anträge werden unter "Einstellungen → Verifizierung" gestellt und manuell von Moderatoren geprüft — eine automatische Freigabe gibt es nicht. Das Profil muss mindestens zu 80 % vollständig sein (Avatar, Fursona, E-Mail).',
    helpFaqQ3: 'Wie erstelle ich eine Gruppe und wer kann sie verwalten?',
    helpFaqA3: 'Klicke auf "Erstellen" im Bereich "Gruppen". Der Ersteller wird automatisch Eigentümer und kann die Rechte über einen einmaligen Bestätigungscode in den Gruppeneinstellungen an ein anderes Mitglied übertragen.',
    helpFaqQ4: "Was ist Dealers' Den?",
    helpFaqA4: "Dealers' Den ist ein Marktplatz für Künstler und Handwerker: Verkäufer-Schaufenster, Angebote, Gebote, Messen und ein Reputationssystem (Trust Score). Du kannst dein eigenes Schaufenster über den Bereich Dealers' Den in der Seitenleiste eröffnen.",
    helpFaqQ5: 'Wie funktionieren Sticker und der Shop?',
    helpFaqA5: 'Im "Shop" kannst du Sticker-Pakete mit In-App-Währung oder echtem Geld kaufen. Gekaufte Pakete erscheinen in deiner Sammlung und stehen beim Senden von Nachrichten und Kommentaren zur Verfügung.',
    helpFaqQ6: 'Was macht der Bereich "Automatisierung"?',
    helpFaqA6: 'Die Automatisierung hilft dir, wiederkehrende Aktionen und Erinnerungen im Zusammenhang mit Aktivitäten und Aufgaben innerhalb der Plattform einzurichten.',
    helpFaqQ7: 'Mein Konto ist eingefroren oder gesperrt — was tun?',
    helpFaqA7: 'Bei einem eingefrorenen Konto wird auf dem Login-Bildschirm angeboten, deine Identität per Einmalcode per E-Mail zu bestätigen und das Konto selbst zu entsperren. Bei einer Sperrung wende dich über "Problem melden" unten oder an support@bloomly.fun, unter Angabe deines Benutzernamens und des Anliegens.',
    helpFaqQ8: 'Wie konfiguriere ich die Privatsphäre meines Profils?',
    helpFaqA8: 'Unter "Einstellungen → Privatsphäre" kannst du separat einschränken, wer deine Freundesliste und deinen Online-Status sieht oder dir Nachrichten senden bzw. deine Beiträge kommentieren kann: "alle", "nur Freunde" oder "nur ich".',
    helpFaqQ9: 'Wie melde ich einen Beitrag, Kommentar oder Nutzer?',
    helpFaqA9: 'Die meisten Beiträge, Kommentare und Profile haben eine Schaltfläche mit einem Flaggen-Symbol — sie sendet eine Meldung direkt an die Moderatoren, ohne den Support kontaktieren zu müssen.',
    helpFaqQ10: 'Kann ich meine Daten löschen oder exportieren?',
    helpFaqA10: 'Ja. Der Datenexport und die Kontolöschung sind unter "Einstellungen → Profil" ganz unten auf der Seite verfügbar. Details zur Datenverarbeitung findest du in der Datenschutzrichtlinie.',
    helpReportIntro: 'Beschreibe einen Fehler, eine Idee oder eine Frage — Moderatoren sehen sie und antworten direkt hier, im Tab "Meine Anfragen".',
