    help: 'Aide',
    helpSubtitle: 'FAQ, support et contacts de Bloomly',
    helpTabFaq: 'Questions fréquentes',
    helpTabReport: 'Signaler un problème',
    helpTabTickets: 'Mes demandes',
    helpTabContacts: 'Contacts',
    helpFaqQ1: 'Comment changer ma photo de profil ou ma bannière?',
    helpFaqA1: "Allez dans « Paramètres → Profil » et cliquez sur votre avatar ou votre bannière pour importer une nouvelle image. Vous pouvez recadrer l'avatar directement dans l'éditeur avant d'enregistrer.",
    helpFaqQ2: "Qu'est-ce que la vérification et comment l'obtenir?",
    helpFaqA2: "La vérification confirme qu'un compte appartient à une personne réelle et correspond à l'une des catégories suivantes : artiste, artisan, fursuiter, écrivain, organisateur, etc. Les demandes se font depuis « Paramètres → Vérification » et sont examinées manuellement par les modérateurs — il n'y a pas d'approbation automatique. Le profil doit être complété à au moins 80 % (avatar, fursona, e-mail).",
    helpFaqQ3: 'Comment créer un groupe et qui peut le gérer?',
    helpFaqA3: 'Cliquez sur « Créer » dans la section « Groupes ». Le créateur devient automatiquement propriétaire et peut transférer les droits à un autre membre via un code de confirmation à usage unique dans les paramètres du groupe.',
    helpFaqQ4: "Qu'est-ce que Dealers' Den?",
    helpFaqA4: "Dealers' Den est une place de marché pour les artistes et artisans : vitrines de vendeurs, annonces, enchères, foires et un système de réputation (Trust Score). Ouvrez votre propre vitrine depuis la section Dealers' Den dans la barre latérale.",
    helpFaqQ5: 'Comment fonctionnent les stickers et la boutique?',
    helpFaqA5: "La « Boutique » permet d'acheter des packs de stickers avec la monnaie de l'application ou de l'argent réel. Les packs achetés apparaissent dans votre collection et sont disponibles lors de l'envoi de messages et de commentaires.",
    helpFaqQ6: 'À quoi sert la section « Automatisation »?',
    helpFaqA6: "L'automatisation permet de configurer des actions récurrentes et des rappels liés aux activités et tâches au sein de la plateforme.",
    helpFaqQ7: 'Mon compte est gelé ou banni — que faire?',
    helpFaqA7: "Pour un compte gelé, l'écran de connexion proposera de confirmer votre identité via un code à usage unique envoyé par e-mail et de dégeler le compte vous-même. En cas de bannissement, contactez le support via « Signaler un problème » ci-dessous ou à support@bloomly.fun, en indiquant votre nom d'utilisateur et le problème.",
    helpFaqQ8: 'Comment configurer la confidentialité du profil?',
    helpFaqA8: "Dans « Paramètres → Confidentialité », vous pouvez restreindre séparément qui voit votre liste d'amis, votre statut en ligne, ou peut vous envoyer des messages ou commenter vos publications : « tout le monde », « amis uniquement » ou « moi uniquement ».",
    helpFaqQ9: 'Comment signaler une publication, un commentaire ou un utilisateur?',
    helpFaqA9: "La plupart des publications, commentaires et profils ont un bouton avec une icône de drapeau — il envoie un signalement directement aux modérateurs, sans avoir besoin de contacter le support.",
    helpFaqQ10: 'Puis-je supprimer ou exporter mes données?',
    helpFaqA10: "Oui. L'export des données et la suppression du compte sont disponibles dans « Paramètres → Profil », tout en bas de la page. Les détails du traitement des données sont décrits dans la Politique de confidentialité.",
    helpReportIntro: "Décrivez un bug, une idée ou une question — les modérateurs la verront et répondront directement ici, dans l'onglet « Mes demandes ».",
