    help: 'Ayuda',
    helpSubtitle: 'Preguntas frecuentes, soporte y contactos de Bloomly',
    helpTabFaq: 'Preguntas frecuentes',
    helpTabReport: 'Reportar un problema',
    helpTabTickets: 'Mis solicitudes',
    helpTabContacts: 'Contactos',
    helpFaqQ1: '¿Cómo cambio mi foto de perfil o banner?',
    helpFaqA1: 'Ve a «Configuración → Perfil» y haz clic en tu avatar o banner para subir una nueva imagen. Puedes recortar el avatar directamente en el editor antes de guardar.',
    helpFaqQ2: '¿Qué es la verificación y cómo la obtengo?',
    helpFaqA2: 'La verificación confirma que una cuenta pertenece a una persona real y corresponde a una de las categorías: artista, artesano, fursuiter, escritor, organizador, etc. Las solicitudes se envían desde «Configuración → Verificación» y son revisadas manualmente por los moderadores — no hay aprobación automática. El perfil debe estar completo al menos en un 80 % (avatar, fursona, correo electrónico).',
    helpFaqQ3: '¿Cómo creo un grupo y quién puede administrarlo?',
    helpFaqA3: 'Haz clic en «Crear» en la sección «Grupos». El creador se convierte automáticamente en propietario y puede transferir los derechos a otro miembro mediante un código de confirmación de un solo uso en la configuración del grupo.',
    helpFaqQ4: "¿Qué es Dealers' Den?",
    helpFaqA4: "Dealers' Den es un mercado para artistas y artesanos: escaparates de vendedores, anuncios, pujas, ferias y un sistema de reputación (Trust Score). Puedes abrir tu propio escaparate desde la sección Dealers' Den en la barra lateral.",
    helpFaqQ5: '¿Cómo funcionan los stickers y la tienda?',
    helpFaqA5: 'En la «Tienda» puedes comprar paquetes de stickers con moneda interna o dinero real. Los paquetes comprados aparecen en tu colección y están disponibles al enviar mensajes y comentarios.',
    helpFaqQ6: '¿Qué hace la sección «Automatización»?',
    helpFaqA6: 'La automatización te ayuda a configurar acciones recurrentes y recordatorios relacionados con actividades y tareas dentro de la plataforma.',
    helpFaqQ7: 'Mi cuenta está congelada o baneada, ¿qué hago?',
    helpFaqA7: 'Si la cuenta está congelada, la pantalla de inicio de sesión te ofrecerá confirmar tu identidad con un código de un solo uso por correo y descongelarla tú mismo. Si está baneada, contacta con soporte mediante «Reportar un problema» abajo o en support@bloomly.fun, indicando tu nombre de usuario y el problema.',
    helpFaqQ8: '¿Cómo configuro la privacidad de mi perfil?',
    helpFaqA8: 'En «Configuración → Privacidad» puedes restringir por separado quién ve tu lista de amigos, tu estado en línea, o puede enviarte mensajes o comentar tus publicaciones: «todos», «solo amigos» o «solo yo».',
    helpFaqQ9: '¿Cómo reporto una publicación, comentario o usuario?',
    helpFaqA9: 'La mayoría de las publicaciones, comentarios y perfiles tienen un botón con un icono de bandera — envía un reporte directamente a los moderadores sin necesidad de contactar con soporte.',
    helpFaqQ10: '¿Puedo eliminar o exportar mis datos?',
    helpFaqA10: 'Sí. La exportación de datos y la eliminación de la cuenta están disponibles en «Configuración → Perfil», al final de la página. Los detalles del tratamiento de datos se describen en la Política de privacidad.',
    helpReportIntro: 'Describe un error, una idea o una pregunta — los moderadores la verán y responderán aquí mismo, en la pestaña «Mis solicitudes».',
