    dealersDen: "Dealers' Den",
    help: 'Ajuda',
    helpSubtitle: 'Perguntas frequentes, suporte e contatos da Bloomly',
    helpTabFaq: 'Perguntas frequentes',
    helpTabReport: 'Reportar um problema',
    helpTabTickets: 'Minhas solicitações',
    helpTabContacts: 'Contatos',
    helpFaqQ1: 'Como altero minha foto de perfil ou banner?',
    helpFaqA1: 'Vá em «Configurações → Perfil» e clique no avatar ou banner para enviar uma nova imagem. Você pode recortar o avatar diretamente no editor antes de salvar.',
    helpFaqQ2: 'O que é a verificação e como obtê-la?',
    helpFaqA2: 'A verificação confirma que uma conta pertence a uma pessoa real e se enquadra em uma das categorias: artista, artesão, fursuiter, escritor, organizador etc. As solicitações são enviadas em «Configurações → Verificação» e analisadas manualmente pelos moderadores — não há aprovação automática. O perfil deve estar pelo menos 80% completo (avatar, fursona, e-mail).',
    helpFaqQ3: 'Como crio um grupo e quem pode administrá-lo?',
    helpFaqA3: 'Clique em «Criar» na seção «Grupos». O criador se torna automaticamente o proprietário e pode transferir os direitos para outro membro por meio de um código de confirmação único nas configurações do grupo.',
    helpFaqQ4: "O que é a Dealers' Den?",
    helpFaqA4: "A Dealers' Den é um marketplace para artistas e artesãos: vitrines de vendedores, anúncios, lances, feiras e um sistema de reputação (Trust Score). Você pode abrir sua própria vitrine na seção Dealers' Den, na barra lateral.",
    helpFaqQ5: 'Como funcionam os stickers e a loja?',
    helpFaqA5: 'Na «Loja» você pode comprar pacotes de stickers com moeda interna ou dinheiro real. Os pacotes comprados aparecem na sua coleção e ficam disponíveis ao enviar mensagens e comentários.',
    helpFaqQ6: 'O que a seção «Automação» faz?',
    helpFaqA6: 'A automação ajuda a configurar ações recorrentes e lembretes relacionados a atividades e tarefas dentro da plataforma.',
    helpFaqQ7: 'Minha conta está congelada ou banida — o que faço?',
    helpFaqA7: 'Se a conta estiver congelada, a tela de login oferecerá confirmar sua identidade com um código único por e-mail e descongelá-la você mesmo. Se estiver banida, entre em contato com o suporte pelo «Reportar um problema» abaixo ou em support@bloomly.fun, informando seu nome de usuário e o problema.',
    helpFaqQ8: 'Como configuro a privacidade do perfil?',
    helpFaqA8: 'Em «Configurações → Privacidade» você pode restringir separadamente quem vê sua lista de amigos, status online, ou pode enviar mensagens ou comentar em suas publicações: «todos», «somente amigos» ou «somente eu».',
    helpFaqQ9: 'Como denuncio uma publicação, comentário ou usuário?',
    helpFaqA9: 'A maioria das publicações, comentários e perfis tem um botão com ícone de bandeira — ele envia uma denúncia diretamente aos moderadores, sem necessidade de contatar o suporte.',
    helpFaqQ10: 'Posso excluir ou exportar meus dados?',
    helpFaqA10: 'Sim. A exportação de dados e a exclusão da conta estão disponíveis em «Configurações → Perfil», bem no final da página. Os detalhes do tratamento de dados estão descritos na Política de Privacidade.',
    helpReportIntro: 'Descreva um bug, uma ideia ou uma pergunta — os moderadores verão e responderão aqui mesmo, na aba «Minhas solicitações».',
